            bad = matches(res, c["expect"])
            line += "   OK" if not bad else "   FAIL: " + "; ".join(bad)
            fails += bool(bad)
        print(line)
    return 1 if fails else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

