            if not q and ch == "(":
                depth += 1
                ch = " "
            elif not q and ch == ")":
                depth -= 1
                ch = " "
            out += ch
        if not buf:
            first_blank = out[:1] in (" ", "\t")
        buf += out + " "
        if depth <= 0:
            if buf.strip():
                yield first_blank, buf
            buf, depth = "", 0
    if buf.strip():
