    pass


def ttl_value(s):
    m = re.fullmatch(r"(?:\d+[smhdwSMHDW]?)+", s)
    if not m:
        return None
    return sum(int(n) * UNITS[(u or "s").lower()] for n, u in re.findall(r"(\d+)([smhdwSMHDW]?)", s))


def absname(n, origin):
    if n == "@":
        return origin
    if n.endswith("."):
        return n.lower()
    return (n + "." + origin).lower()


